package com.gerenciadorrural.modules.inventory.infrastructure;
import com.gerenciadorrural.modules.inventory.domain.*; import com.gerenciadorrural.modules.inventory.application.InventoryService.*; import com.gerenciadorrural.shared.tenancy.TenantId; import org.springframework.dao.*; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository; import java.math.*; import java.sql.*; import java.time.*; import java.util.*; import static com.gerenciadorrural.modules.inventory.domain.InventoryModels.*;
@Repository public class JdbcInventoryRepository implements InventoryRepository {private final NamedParameterJdbcTemplate j;public JdbcInventoryRepository(NamedParameterJdbcTemplate j){this.j=j;}private MapSqlParameterSource p(TenantId t){return new MapSqlParameterSource("t",t.value());}
 public Optional<Product> product(TenantId t,UUID id,boolean lock){return j.query("select * from app.inventory_products where tenant_id=:t and id=:id"+(lock?" for update":""),p(t).addValue("id",id),(r,n)->product(r)).stream().findFirst();}public Optional<Location> location(TenantId t,UUID f,UUID id,boolean lock){return j.query("select * from app.inventory_locations where tenant_id=:t and farm_id=:f and id=:id"+(lock?" for update":""),p(t).addValue("f",f).addValue("id",id),(r,n)->location(r)).stream().findFirst();}
 public Product insertProduct(TenantId t,Product x){j.update("insert into app.inventory_products(id,tenant_id,name,code,category,base_unit,status) values(:id,:t,:n,:c,:g,:u,:s)",p(t).addValue("id",x.id()).addValue("n",x.name()).addValue("c",x.code()).addValue("g",x.category()).addValue("u",x.baseUnit().name()).addValue("s",x.status().name()));return product(t,x.id(),false).orElseThrow();} public Location insertLocation(TenantId t,UUID f,Location x){j.update("insert into app.inventory_locations(id,tenant_id,farm_id,name,code,status) values(:id,:t,:f,:n,:c,:s)",p(t).addValue("f",f).addValue("id",x.id()).addValue("n",x.name()).addValue("c",x.code()).addValue("s",x.status().name()));return location(t,f,x.id(),false).orElseThrow();}
 public Product updateProduct(TenantId t,Product x,long v){if(j.update("update app.inventory_products set name=:n,code=:c,category=:g,status=:s,version=version+1,updated_at=current_timestamp where tenant_id=:t and id=:id and version=:v",p(t).addValue("id",x.id()).addValue("n",x.name()).addValue("c",x.code()).addValue("g",x.category()).addValue("s",x.status().name()).addValue("v",v))==0)throw new Conflict();return product(t,x.id(),false).orElseThrow();}public Location updateLocation(TenantId t,UUID f,Location x,long v){if(j.update("update app.inventory_locations set name=:n,code=:c,status=:s,version=version+1,updated_at=current_timestamp where tenant_id=:t and farm_id=:f and id=:id and version=:v",p(t).addValue("f",f).addValue("id",x.id()).addValue("n",x.name()).addValue("c",x.code()).addValue("s",x.status().name()).addValue("v",v))==0)throw new Conflict();return location(t,f,x.id(),false).orElseThrow();}
 public BigDecimal productTotal(TenantId t,UUID x){return j.queryForObject("select coalesce(sum(quantity),0) from app.inventory_balances where tenant_id=:t and product_id=:id",p(t).addValue("id",x),BigDecimal.class);}public BigDecimal locationTotal(TenantId t,UUID f,UUID x){return j.queryForObject("select coalesce(sum(quantity),0) from app.inventory_balances where tenant_id=:t and farm_id=:f and location_id=:id",p(t).addValue("f",f).addValue("id",x),BigDecimal.class);}
 public Optional<String> operation(TenantId t,UUID f,UUID o){MapSqlParameterSource q=p(t).addValue("f",f).addValue("o",o);j.query("select pg_advisory_xact_lock(hashtext(cast(:t as text)||cast(:f as text)||cast(:o as text)))",q,(r,n)->0);return j.query("select command_payload from app.inventory_operations where tenant_id=:t and farm_id=:f and operation_id=:o for update",q,(r,n)->r.getString(1)).stream().findFirst();}public void saveOperation(TenantId t,UUID f,UUID o,String x){j.update("insert into app.inventory_operations(tenant_id,farm_id,operation_id,command_payload) values(:t,:f,:o,:x)",p(t).addValue("f",f).addValue("o",o).addValue("x",x));}
 public BigDecimal changeBalance(TenantId t,UUID f,UUID l,UUID product,BigDecimal delta){MapSqlParameterSource q=p(t).addValue("f",f).addValue("l",l).addValue("p",product);j.update("insert into app.inventory_balances(tenant_id,farm_id,location_id,product_id,quantity) values(:t,:f,:l,:p,0) on conflict do nothing",q);BigDecimal current=j.query("select quantity from app.inventory_balances where tenant_id=:t and farm_id=:f and location_id=:l and product_id=:p for update",q,(r,n)->r.getBigDecimal(1)).stream().findFirst().orElse(BigDecimal.ZERO), next=current.add(delta);if(next.signum()<0)throw new Insufficient();j.update("update app.inventory_balances set quantity=:q,version=version+1,updated_at=current_timestamp where tenant_id=:t and farm_id=:f and location_id=:l and product_id=:p",q.addValue("q",next));return next;}
 public void movement(TenantId t,UUID f,Movement m){j.update("insert into app.inventory_movements(id,tenant_id,farm_id,operation_id,movement_type,product_id,product_name,base_unit,source_location_id,source_location_name,destination_location_id,destination_location_name,quantity,source_balance_after,destination_balance_after,occurred_on,actor_user_id,notes) values(:id,:t,:f,:o,:y,:p,:pn,:u,:sl,:sn,:dl,:dn,:q,:sq,:dq,:d,:a,:n)",p(t).addValue("f",f).addValue("id",m.id()).addValue("o",m.operationId()).addValue("y",m.type().name()).addValue("p",m.productId()).addValue("pn",m.productName()).addValue("u",m.baseUnit().name()).addValue("sl",m.sourceLocationId()).addValue("sn",m.sourceLocationName()).addValue("dl",m.destinationLocationId()).addValue("dn",m.destinationLocationName()).addValue("q",m.quantity()).addValue("sq",m.sourceBalanceAfter()).addValue("dq",m.destinationBalanceAfter()).addValue("d",m.occurredOn()).addValue("a",m.actorUserId()).addValue("n",m.notes()));}public Optional<Movement> movementByOperation(TenantId t,UUID f,UUID o){return j.query("select * from app.inventory_movements where tenant_id=:t and farm_id=:f and operation_id=:o",p(t).addValue("f",f).addValue("o",o),(r,n)->movement(r)).stream().findFirst();}
 public List<Product> products(TenantId t){return j.query("select * from app.inventory_products where tenant_id=:t order by name,id",p(t),(r,n)->product(r));}public List<Location> locations(TenantId t,UUID f){return j.query("select * from app.inventory_locations where tenant_id=:t and farm_id=:f order by name,id",p(t).addValue("f",f),(r,n)->location(r));}
 public List<Balance> balances(TenantId t,UUID f,UUID l,UUID product,String search,boolean pos,int size,long offset){return j.query("select b.*,p.name product_name,p.base_unit,l.name location_name from app.inventory_balances b join app.inventory_products p on p.tenant_id=b.tenant_id and p.id=b.product_id join app.inventory_locations l on l.tenant_id=b.tenant_id and l.farm_id=b.farm_id and l.id=b.location_id where b.tenant_id=:t and b.farm_id=:f and (cast(:l as uuid) is null or b.location_id=:l) and (cast(:p as uuid) is null or b.product_id=:p) and (cast(:s as text) is null or lower(p.name) like lower(:s)) and (:pos=false or b.quantity>0) order by p.name,b.location_id limit :z offset :off",p(t).addValue("f",f).addValue("l",l).addValue("p",product).addValue("s",search==null?null:"%"+search.replace("%","\\%").replace("_","\\_")+"%").addValue("pos",pos).addValue("z",size).addValue("off",offset),(r,n)->balance(r));} public long balanceCount(TenantId t,UUID f,UUID l,UUID product,String s,boolean pos){return balances(t,f,l,product,s,pos,100000,0).size();}
 public List<Movement> movements(TenantId t,UUID f,Type y,UUID p,UUID l,LocalDate from,LocalDate to,int z,long off){return j.query("select * from app.inventory_movements where tenant_id=:t and farm_id=:f and (cast(:y as text) is null or movement_type=:y) and (cast(:p as uuid) is null or product_id=:p) and (cast(:l as uuid) is null or source_location_id=:l or destination_location_id=:l) and (cast(:from as date) is null or occurred_on>=:from) and (cast(:to as date) is null or occurred_on<=:to) order by recorded_at desc,id desc limit :z offset :off",p(t).addValue("f",f).addValue("y",y==null?null:y.name()).addValue("p",p).addValue("l",l).addValue("from",from).addValue("to",to).addValue("z",z).addValue("off",off),(r,n)->movement(r));}public long movementCount(TenantId t,UUID f,Type y,UUID p,UUID l,LocalDate from,LocalDate to){return movements(t,f,y,p,l,from,to,100000,0).size();}public Optional<Movement> movement(TenantId t,UUID f,UUID id){return j.query("select * from app.inventory_movements where tenant_id=:t and farm_id=:f and id=:id",p(t).addValue("f",f).addValue("id",id),(r,n)->movement(r)).stream().findFirst();}
 private static Product product(ResultSet r)throws SQLException{return new Product(r.getObject("id",UUID.class),r.getString("name"),r.getString("code"),r.getString("category"),Unit.valueOf(r.getString("base_unit")),Status.valueOf(r.getString("status")),r.getLong("version"),r.getObject("created_at",OffsetDateTime.class).toInstant(),r.getObject("updated_at",OffsetDateTime.class).toInstant());}private static Location location(ResultSet r)throws SQLException{return new Location(r.getObject("id",UUID.class),r.getString("name"),r.getString("code"),Status.valueOf(r.getString("status")),r.getLong("version"),r.getObject("created_at",OffsetDateTime.class).toInstant(),r.getObject("updated_at",OffsetDateTime.class).toInstant());}private static Balance balance(ResultSet r)throws SQLException{return new Balance(r.getObject("product_id",UUID.class),r.getString("product_name"),Unit.valueOf(r.getString("base_unit")),r.getObject("location_id",UUID.class),r.getString("location_name"),r.getBigDecimal("quantity"),r.getLong("version"),r.getObject("updated_at",OffsetDateTime.class).toInstant());}private static Movement movement(ResultSet r)throws SQLException{return new Movement(r.getObject("id",UUID.class),r.getObject("operation_id",UUID.class),Type.valueOf(r.getString("movement_type")),r.getObject("product_id",UUID.class),r.getString("product_name"),Unit.valueOf(r.getString("base_unit")),r.getObject("source_location_id",UUID.class),r.getString("source_location_name"),r.getObject("destination_location_id",UUID.class),r.getString("destination_location_name"),r.getBigDecimal("quantity"),r.getBigDecimal("source_balance_after"),r.getBigDecimal("destination_balance_after"),r.getObject("occurred_on",LocalDate.class),r.getObject("actor_user_id",UUID.class),r.getString("notes"),r.getObject("recorded_at",OffsetDateTime.class).toInstant());}}
